"""重建自包含离线教材。仅维护教材时需要markdown-it-py；阅读HTML和课程工具不需要它。"""
from pathlib import Path
import hashlib,html,json,re
from urllib.parse import unquote
from markdown_it import MarkdownIt
ROOT=Path(__file__).resolve().parents[1]
manifest=json.loads((ROOT/'course-manifest.json').read_text(encoding='utf-8'))
files=sorted(p for p in ROOT.rglob('*') if p.is_file() and p.suffix in {'.md','.py','.java','.sql','.json','.in','.log','.toml'} and '__pycache__' not in p.parts and '.local' not in p.parts and p.name!='release-manifest.json' and 'history-v4' not in p.parts)
ids={p.resolve():'d'+hashlib.sha1(p.relative_to(ROOT).as_posix().encode()).hexdigest()[:12] for p in files}
md=MarkdownIt('commonmark',{'html':False,'typographer':False}).enable('table')
docs={};path_ids={}
for p in files:
    rel=p.relative_to(ROOT).as_posix();raw=p.read_text(encoding='utf-8');id=ids[p.resolve()];path_ids[rel]=id
    if p.suffix=='.md':
        tokens=md.parse(raw)
        for t in tokens:
            for c in t.children or []:
                if c.type=='link_open':
                    href=c.attrGet('href') or ''
                    if re.match(r'^[a-zA-Z]+:',href):c.attrSet('target','_blank');c.attrSet('rel','noopener noreferrer')
                    elif href and not href.startswith('#'):
                        target=(p.parent/unquote(href.split('#')[0])).resolve()
                        if target in ids:c.attrSet('href','#'+ids[target])
            if t.type=='table_open':t.meta['wrapper']=True
        body=md.renderer.render(tokens,md.options,{})
        body=body.replace('<table>','<div class="table-scroll"><table>').replace('</table>','</table></div>')
        title=next((x.lstrip('# ').strip() for x in raw.splitlines() if x.startswith('# ')),p.name)
    else:
        body='<h1>'+html.escape(p.name)+'</h1><p class="code-note">文件内容预览。运行时使用完整压缩包中的同名文件；这里不会执行代码。</p><pre><code>'+html.escape(raw)+'</code></pre>'
        title=p.name
    lesson=p.parent.name if p.parent.parent.name=='lessons' else None
    docs[id]={'id':id,'path':rel,'title':title,'html':body,'raw':raw,'lesson':lesson,'answer':(p.name.startswith('04-') and lesson is not None) or ('answers' in p.parts and 'workshops' in p.parts)}
lessons=[]
for l in manifest['order']:
    d=manifest['lessons'][l]
    tabs=[]
    for label,name in [('00 目的与文件','00-本课目的与文件导航.md'),('01 教程','01-教程.md'),('02 给Codex','02-交给AI.md'),('03 实验步骤','03-实验与排错.md'),('05 源码定位','05-过关卡与代码地图.md'),('04 参考答案','04-复习与迁移答案.md')]:tabs.append({'label':label,'id':path_ids[f'lessons/{l}/{name}']})
    extra=[{'label':p.name,'id':ids[p.resolve()]} for p in files if p.parent==ROOT/'lessons'/l and p.suffix!='.md']
    lessons.append({'id':l,'title':d['title'],'hours':d['hours'],'weeks':d['weeks'],'tabs':tabs,'examples':extra})
root_items=[{'label':p.stem,'id':ids[p.resolve()]} for p in sorted(ROOT.glob('*.md')) if p.name!='README.md']
roots_extra=['workshops/README.md','validation/report.md']
for path in roots_extra:root_items.append({'label':'独立排错练习' if path.startswith('workshops') else '本次实际验证报告','id':path_ids[path]})
data={'docs':docs,'lessons':lessons,'roots':root_items,'start':path_ids['00-从这里开始.md'],'catalog':path_ids['01-课程导航.md'],'report':path_ids['validation/report.md'],'l00':path_ids['lessons/L00/00-本课目的与文件导航.md'],'current_lesson':path_ids['lessons/L02/01-教程.md']}
