js=r'''
const D=JSON.parse(document.getElementById('course-data').textContent);let current=null,unlocked=new Set();
const $=s=>document.querySelector(s);const escapeHTML=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function navButton(id,label,extra=''){return `<button class="navlink" data-doc="${id}" onclick="go('${id}')">${label}${extra}</button>`;}
function nav(){let q=$('#search').value.trim().toLowerCase(),out='';if(q){let hits=Object.values(D.docs).filter(x=>(!x.answer||unlocked.has(x.id))&&(x.path+' '+x.title+' '+x.raw).toLowerCase().includes(q));out=`<div class="navheading">搜索结果 · ${hits.length}</div>`+hits.slice(0,50).map(x=>navButton(x.id,escapeHTML(x.title),`<span class="navfine">${escapeHTML(x.path)}</span>`)).join('');if(!hits.length)out+='<p class="searchempty">没有匹配结果。试试课号、函数名或工程现象。</p>';}else{out='<div class="navheading">开始 / 路线</div>'+D.roots.slice(0,2).map(x=>navButton(x.id,escapeHTML(x.label))).join('')+'<div class="navheading">34课 · 按依赖顺序学习</div>';out+=D.lessons.map(l=>navButton(l.tabs[0].id,`<b>${l.id}</b><span class="navtitle">${escapeHTML(l.title)}</span>`,`<span class="navfine">${l.hours}小时 · 第${l.weeks.join(' / ')}周</span>`)).join('');out+='<div class="navheading">需要时再读 / 工具与证据</div>'+D.roots.slice(2).map(x=>navButton(x.id,escapeHTML(x.label))).join('');}$('#navigation').innerHTML=out;highlight();}
function highlight(){document.querySelectorAll('.navlink').forEach(e=>{const d=D.docs[e.dataset.doc];e.classList.toggle('active',e.dataset.doc===current||(d&&D.docs[current]&&d.lesson&&d.lesson===D.docs[current].lesson&&d.path.endsWith('00-本课目的与文件导航.md')));});}
function go(id){if(!D.docs[id])id=D.start;render(id);location.hash=id;document.body.classList.remove('mobile-nav');}
function render(id){if(!D.docs[id])id=D.start;current=id;let doc=D.docs[id],l=D.lessons.find(x=>x.id===doc.lesson);document.title=doc.title+' · DevAgent v5.0';$('#breadcrumb').textContent=doc.lesson?`DevAgent v5.0 / ${doc.lesson} / ${doc.path.split('/').pop()}`:'DevAgent v5.0 / '+doc.title;$('#docpath').textContent=doc.path;$('#hero').hidden=id!==D.start;$('#copy').textContent=doc.path.endsWith('02-交给AI.md')?'复制本课完整AI指令':'复制当前文件';$('#copy').disabled=false;$('#lessonhead').hidden=!l;
if(l){$('#lessonmeta').textContent=`${l.id} · ${l.hours}小时预算 · 第${l.weeks.join(' / ')}周 · 先看具体方案 → 定位真实代码 → 验证一个行为`;$('#tabs').innerHTML=l.tabs.map(t=>`<button class="tab ${t.id===id?'active':''}" onclick="go('${t.id}')">${t.label}</button>`).join('');$('#examples').innerHTML='<span>教材内已有例子（非已生成项目）：</span>'+l.examples.map(x=>`<a href="#${x.id}">${escapeHTML(x.label)}</a>`).join('');}
let gated=doc.answer&&!unlocked.has(doc.id);$('#answerGate').hidden=!gated;$('#article').hidden=gated;$('#toc').hidden=gated;$('#copy').hidden=gated;
if(gated){$('#article').innerHTML='';$('#toc').innerHTML='';}else{$('#article').innerHTML=doc.html;let headings=[...$('#article').querySelectorAll('h2')];headings.forEach((h,i)=>h.id=id+'-h'+i);$('#toc').hidden=headings.length<3;$('#toc').innerHTML='<summary>本页内容</summary>'+headings.map(h=>`<a href="#${h.id}" data-scroll="${h.id}">${escapeHTML(h.textContent)}</a>`).join('');}
let i=l?D.lessons.indexOf(l):-1;$('#prev').hidden=i<=0;$('#next').hidden=i<0||i===D.lessons.length-1;if(i>0){$('#prev').textContent='← 上一课 '+D.lessons[i-1].id;$('#prev').onclick=()=>go(D.lessons[i-1].tabs[0].id);}if(i>=0&&i<D.lessons.length-1){$('#next').textContent='下一课 '+D.lessons[i+1].id+' →';$('#next').onclick=()=>go(D.lessons[i+1].tabs[0].id);}highlight();try{localStorage.setItem('devagent-v5-last-document',id);}catch(e){}window.scrollTo(0,0);}
function unlock(){unlocked.add(current);render(current);nav();}
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,3200);}
async function copyDoc(){const text=D.docs[current].raw;try{if(navigator.clipboard&&navigator.clipboard.writeText){await navigator.clipboard.writeText(text);toast('已复制当前完整文件；未附加答案或其他课程。');return;}}catch(e){}$('#copyText').value=text;$('#copyModal').hidden=false;$('#copyText').focus();$('#copyText').select();toast('浏览器限制剪贴板，请在已选中文本上复制。');}
function resume(){let id=D.start;try{id=localStorage.getItem('devagent-v5-last-document')||D.start;}catch(e){}go(id);}
$('#search').addEventListener('input',nav);$('#menu').onclick=()=>document.body.classList.toggle('mobile-nav');$('#closeNav').onclick=()=>document.body.classList.remove('mobile-nav');$('#copy').onclick=copyDoc;$('#unlock').onclick=unlock;$('#closeModal').onclick=()=>$('#copyModal').hidden=true;
document.addEventListener('click',e=>{let a=e.target.closest('[data-scroll]');if(a){e.preventDefault();document.getElementById(a.dataset.scroll)?.scrollIntoView({block:'start'});}});window.addEventListener('hashchange',()=>{let id=location.hash.slice(1);if(D.docs[id]&&id!==current)render(id);});document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('mobile-nav');$('#copyModal').hidden=true;}});nav();render(location.hash.slice(1)||D.start);
'''
payload=json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
